rss.channel:
    {{ site.title | xml_escape }}{% if page.feed_lang == 'zh' %} · 中文{% endif %}
    {{ site.description | xml_escape }}
    {% if page.feed_lang == 'zh' %}zh-Hans{% else %}en{% endif %}
    {{ '/' | absolute_url }}

    {{ site.time | date_to_rfc822 }}
    {% for post in site.posts limit:10 %}
      {% assign feed_parts = post.content | split: '' %}
      {% assign feed_content = feed_parts | first %}
      {% assign feed_title = post.title %}
      {% assign entry_language = 'en' %}
      {% if page.feed_lang == 'zh' and post.title_zh %}
        {% assign feed_content = feed_parts | last %}
        {% assign feed_title = post.title_zh %}
        {% assign entry_language = 'zh' %}
      {% elsif post.lang_original == 'zh' and post.title_zh == nil %}
        {% assign entry_language = 'zh' %}
      {% endif %}
      {% capture feed_html %}
        {% if page.feed_lang == 'zh' and entry_language == 'en' %}
此篇暂无中文版本，以下为英文原文。{% endif %}
        {% if page.feed_lang == 'en' and entry_language == 'zh' %}
This article is available in Chinese only.{% endif %}
        {% if post.source_url %}

{% if page.feed_lang == 'zh' %}编译：Everett。原文作者：{% else %}Chinese adaptation by Everett. Original by {% endif %}{{ post.source_author | escape }} · {{ post.source_published }} · {% include xnu/external_link.html href=post.source_url label=post.source_title %}
        {% endif %}
        {% if post.historical_context_en %}
{% if page.feed_lang == 'zh' %}历史文章：{{ post.historical_context_zh | escape }} 未按当前版本重新验证。{% else %}Historical note: {{ post.historical_context_en | escape }} Not revalidated against current versions.{% endif %}{% endif %}
        {{ feed_content | markdownify }}
      {% endcapture %}
      {% assign feed_base = site.url | append: site.baseurl %}
      {% assign src_abs = 'src="' | append: feed_base | append: '/' %}
      {% assign href_abs = 'href="' | append: feed_base | append: '/' %}
      {% assign feed_html = feed_html | replace: 'src="/', src_abs | replace: 'href="/', href_abs %}


        {{ feed_title | xml_escape }}
        {{ feed_html | xml_escape }}
        {{ post.date | date_to_rfc822 }}
        {{ post.url | absolute_url }}?lang={{ page.feed_lang }}
        {{ post.url | absolute_url }}
        {% for tag in post.tags %}{{ tag | xml_escape }}{% endfor %}
        {% for cat in post.categories %}{{ cat | xml_escape }}{% endfor %}

    {% endfor %}
